CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('recipe','ingredient')), name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 24), UNIQUE(kind,name));
CREATE TABLE ingredients(id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE CHECK(length(trim(name)) BETWEEN 1 AND 120), category_id TEXT NOT NULL REFERENCES categories(id));
CREATE TABLE recipes(id TEXT PRIMARY KEY, current_revision_id TEXT, category_id TEXT NOT NULL REFERENCES categories(id), archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)));
CREATE TABLE recipe_revisions(id TEXT PRIMARY KEY, recipe_id TEXT NOT NULL REFERENCES recipes(id), revision_number INTEGER NOT NULL CHECK(revision_number>0), name TEXT NOT NULL, subtitle TEXT NOT NULL, minutes INTEGER NOT NULL CHECK(minutes BETWEEN 1 AND 1440), servings INTEGER NOT NULL CHECK(servings BETWEEN 1 AND 12), seasoning TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(recipe_id,revision_number));
CREATE TABLE recipe_ingredients(revision_id TEXT NOT NULL REFERENCES recipe_revisions(id), position INTEGER NOT NULL, ingredient_id TEXT NOT NULL REFERENCES ingredients(id), amount_decimal TEXT NOT NULL, unit TEXT NOT NULL CHECK(unit IN ('g','ml','个','片','盒')), PRIMARY KEY(revision_id,position));
CREATE TABLE recipe_steps(revision_id TEXT NOT NULL REFERENCES recipe_revisions(id), position INTEGER NOT NULL, body TEXT NOT NULL, PRIMARY KEY(revision_id,position));
CREATE TABLE favorite_recipes(recipe_id TEXT PRIMARY KEY REFERENCES recipes(id));
CREATE TABLE inspiration_recipes(recipe_id TEXT PRIMARY KEY REFERENCES recipes(id));
CREATE TABLE cooking_notes(id TEXT PRIMARY KEY, recipe_id TEXT NOT NULL REFERENCES recipes(id), recipe_revision_id TEXT NOT NULL REFERENCES recipe_revisions(id), date TEXT NOT NULL, note TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE command_receipts(request_id TEXT PRIMARY KEY, payload TEXT NOT NULL, committed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE app_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT INTO app_settings VALUES('data_revision','0');
CREATE TRIGGER revisions_no_update BEFORE UPDATE ON recipe_revisions BEGIN SELECT RAISE(ABORT,'immutable revision'); END;
CREATE TRIGGER revisions_no_delete BEFORE DELETE ON recipe_revisions BEGIN SELECT RAISE(ABORT,'immutable revision'); END;
CREATE TRIGGER recipe_ingredients_no_update BEFORE UPDATE ON recipe_ingredients BEGIN SELECT RAISE(ABORT,'immutable revision'); END;
CREATE TRIGGER recipe_ingredients_no_delete BEFORE DELETE ON recipe_ingredients BEGIN SELECT RAISE(ABORT,'immutable revision'); END;
CREATE TRIGGER recipe_steps_no_update BEFORE UPDATE ON recipe_steps BEGIN SELECT RAISE(ABORT,'immutable revision'); END;
CREATE TRIGGER recipe_steps_no_delete BEFORE DELETE ON recipe_steps BEGIN SELECT RAISE(ABORT,'immutable revision'); END;
CREATE INDEX recipe_revision_parent ON recipe_revisions(recipe_id);
CREATE INDEX cooking_note_parent ON cooking_notes(recipe_id);
